import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom CUDA code for adding a position embedding to x
add2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void add2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ pos_embed,
    float* __restrict__ out,
    int batch_size,
    int num_patches_plus_one,
    int dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = batch_size * num_patches_plus_one * dim;
    if (idx < total_size) {
        int col = idx % dim;
        int row = idx / dim; 
        int patch_idx = row % num_patches_plus_one;
        out[idx] = x[idx] + pos_embed[patch_idx * dim + col];
    }
}

torch::Tensor add2d_cuda(
    torch::Tensor x,
    torch::Tensor pos_embed,
    int batch_size,
    int num_patches_plus_one,
    int dim
) {
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int grid_size = (batch_size * num_patches_plus_one * dim + block_size - 1) / block_size;

    add2d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        pos_embed.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        num_patches_plus_one,
        dim
    );

    return out;
}
"""

add2d_cpp_source = r"""
torch::Tensor add2d_cuda(
    torch::Tensor x,
    torch::Tensor pos_embed,
    int batch_size,
    int num_patches_plus_one,
    int dim
);
"""

# Build/Load the custom extension
add2d = load_inline(
    name="add2d",
    cpp_sources=add2d_cpp_source,
    cuda_sources=add2d_source,
    functions=["add2d_cuda"],
    verbose=False
)


class ModelNew(nn.Module):
    def __init__(self, image_size, patch_size, num_classes, dim, depth, heads, mlp_dim, channels=3, dropout=0.1, emb_dropout=0.1):
        """
        Vision Transformer (ViT) model with a custom CUDA operator to add the positional embedding.
        """
        super(ModelNew, self).__init__()

        assert image_size % patch_size == 0, "Image dimensions must be divisible by the patch size."
        num_patches = (image_size // patch_size) ** 2
        patch_dim = channels * patch_size ** 2

        self.patch_size = patch_size
        self.pos_embedding = nn.Parameter(torch.randn(1, num_patches + 1, dim))
        self.patch_to_embedding = nn.Linear(patch_dim, dim)
        self.cls_token = nn.Parameter(torch.randn(1, 1, dim))
        self.dropout = nn.Dropout(emb_dropout)

        self.transformer = nn.TransformerEncoder(
            nn.TransformerEncoderLayer(d_model=dim, nhead=heads, dim_feedforward=mlp_dim, dropout=dropout),
            num_layers=depth
        )

        self.to_cls_token = nn.Identity()
        self.mlp_head = nn.Sequential(
            nn.Linear(dim, mlp_dim),
            nn.GELU(),
            nn.Dropout(dropout),
            nn.Linear(mlp_dim, num_classes)
        )

    def forward(self, img):
        """
        Forward pass of the Vision Transformer with a custom CUDA operator for adding position embeddings.
        """
        p = self.patch_size

        # Patchifying
        x = img.unfold(2, p, p).unfold(3, p, p).reshape(img.shape[0], -1, p*p*img.shape[1])
        x = self.patch_to_embedding(x)

        # Add the class token
        cls_tokens = self.cls_token.expand(img.shape[0], -1, -1)
        x = torch.cat((cls_tokens, x), dim=1)

        # Use the custom CUDA operator to add positional embeddings
        # x shape: (batch_size, num_patches+1, dim)
        batch_size, num_patches_plus_one, dim = x.shape
        x = add2d.add2d_cuda(x.contiguous(), self.pos_embedding[0].contiguous(), batch_size, num_patches_plus_one, dim)

        x = self.dropout(x)
        x = self.transformer(x)
        x = self.to_cls_token(x[:, 0])
        return self.mlp_head(x)
